 <div class="corruption-data-container">$1</div>
 <div class="status-wrapper">
  <button id="toggle-status-btn" title="切换状态栏显示">-</button>
  <div id="corruption-ui" class="corruption-status-container"></div>
 </div>
 <script>
 document.addEventListener('DOMContentLoaded', () => {

  function parseBlock(blockText) {
   const data = {};
   if (!blockText) return data;
   blockText.trim().split('\n').forEach(line => {
    const parts = line.split(/:(.*)/s);
    if (parts.length >= 2) {
     const key = parts[0].trim();
     const value = parts[1].trim();
     if (key && value) data[key] = value;
    }
   });
   return data;
  }

  function parseData(rawData) {
   const data = { world: {}, allies: [], enemies: [], config: { showSpecificNPCs: true } }; // Default config
   const sections = rawData.split(/\[(世界状态|友军状态|敌军状态|显示设置)\]/);

   for (let i = 1; i < sections.length; i += 2) {
    const type = sections[i];
    const content = sections[i + 1].split(/(\[世界状态\]|\[友军状态\]|\[敌军状态\]|\[显示设置\]|\[腐化关\])/)[0];
    const parsedBlock = parseBlock(content);

    switch(type) {
     case '世界状态': data.world = parsedBlock; break;
     case '友军状态': data.allies.push(parsedBlock); break;
     case '敌军状态': data.enemies.push(parsedBlock); break;
     case '显示设置': data.config.showSpecificNPCs = !(parsedBlock.显示概览 && parsedBlock.显示概览.trim().toLowerCase() === '是'); break;
    }
   }
   return data;
  }

  function setupToggle() {
   const btn = document.getElementById('toggle-status-btn');
   const container = document.getElementById('corruption-ui');
   if (btn && container) {
    btn.addEventListener('click', () => {
     container.classList.toggle('collapsed');
     btn.textContent = container.classList.contains('collapsed') ? '+' : '-';
    });
   }
  }

  function createProgressBar(label, value, max, color) {
   const percentage = (parseInt(value, 10) / parseInt(max, 10)) * 100;
   return `
   <div class="progress-bar-container">
    <div class="progress-bar-label"><span>${label}</span><span>${value}/${max}</span></div>
    <div class="progress-bar-bg">
     <div class="progress-bar-fg" style="width: ${percentage}%; background-color: ${color};"></div>
    </div>
   </div>`;
  }

  function renderUI(data) {
   const container = document.getElementById('corruption-ui');
   if (!container) return;

   let tabsHTML = '';
   let detailsHTML = '';

   // World Tab
   if (data.world && Object.keys(data.world).length > 0) {
       tabsHTML += `<div class="tab-group-label world-label">世界</div>`;
       const worldName = data.world.村庄名称 || '未知地点';
       tabsHTML += `<div class="char-tab world-tab" data-id="${worldName}">${worldName}</div>`;
       detailsHTML += renderWorldDetails(data.world);
   }

   // Allies Tabs
   if (data.allies.length > 0) {
       tabsHTML += `<div class="tab-group-label ally-label">友方</div>`;
       data.allies.forEach(ally => {
           if (data.config.showSpecificNPCs || ['{{user}}', '艾莉诺雅', '芬恩'].includes(ally.姓名)) {
               tabsHTML += `<div class="char-tab ally-tab" data-id="${ally.姓名}">${ally.姓名}</div>`;
               detailsHTML += renderCharacterDetails(ally, 'ally');
           }
       });
   }

   // Enemies Tabs
   if (data.enemies.length > 0) {
       tabsHTML += `<div class="tab-group-label enemy-label">敌方</div>`;
       data.enemies.forEach(enemy => {
           tabsHTML += `<div class="char-tab enemy-tab" data-id="${enemy.姓名}">${enemy.姓名}</div>`;
           detailsHTML += renderCharacterDetails(enemy, 'enemy');
       });
   }

   container.innerHTML = `
    <div class="header-info">
     <div>时间:<span>${data.world.时间 || '未知'}</span></div>
     <div>日期:<span>${data.world.日期 || '未知'}</span></div>
     <div>地点:<span>${data.world.地点 || '未知'}</span></div>
    </div>
    <div class="main-content-wrapper">
     <div class="tabs-wrapper">${tabsHTML}</div>
     <div class="details-wrapper">${detailsHTML}</div>
    </div>
   `;

   setupTabEvents(container);
  }

  function setupTabEvents(container) {
   const tabs = container.querySelectorAll('.char-tab');
   const details = container.querySelectorAll('.detail-card');

   tabs.forEach(tab => {
    tab.addEventListener('click', () => {
     if (tab.classList.contains('active')) return;
     tabs.forEach(t => t.classList.remove('active'));
     tab.classList.add('active');
     details.forEach(detail => detail.classList.remove('active'));
     const targetDetail = container.querySelector(`.detail-card[data-id="${tab.dataset.id}"]`);
     if(targetDetail) targetDetail.classList.add('active');
    });
   });
   if (tabs.length > 0) tabs[0].click();
  }

  function renderWorldDetails(world) {
   const worldName = world.村庄名称 || '未知区域';
   let personnelHTML = '';
   if(world.人员概览) {
       const personnelItems = world.人员概览.split('|').map(item => `<div class="personnel-item">${item.replace(/\(/g, ': ').replace(/\)/g, '')}</div>`).join('');
       personnelHTML = `<div class="detail-section grid-full-width">
           <h3 class="detail-title">人员概览 (总数: ${world.村民总数 || '未知'})</h3>
           <div class="personnel-list">${personnelItems}</div>
       </div>`;
   }

   return `
   <div class="detail-card" data-id="${worldName}">
    <div class="detail-header" style="border-color: var(--primary-color);">
     <h2 class="char-name" style="color:var(--primary-color)">${worldName}</h2>
    </div>
    <div class="details-grid">
     <div class="detail-section">
      <h3 class="detail-title">核心状态</h3>
      ${world.结界强度 ? createProgressBar('结界强度', (world.结界强度 || '0/100').split('/')[0], (world.结界强度 || '0/100').split('/')[1] || 100, 'var(--primary-color)') : '<div class="detail-value">无结界</div>'}
     </div>
     <div class="detail-section">
      <h3 class="detail-title">已知设施</h3>
      <div class="detail-value">${(world.村庄设施 || '无').replace(/\|/g, ' • ')}</div>
     </div>
     ${personnelHTML}
    </div>
   </div>`;
  }

  function renderCharacterDetails(char, type) {
   const colorMap = {
    ally: 'var(--ally-color)', enemy: 'var(--enemy-color)'
   };
   const borderColor = colorMap[type] || 'var(--ally-color)';

   const attrs = ['力量', '敏捷', '体质', '智力', '感知', '魅力'];
   let attrHTML = attrs.map(attr =>
    char[attr] ? `<li class="attr-item"><strong>${attr.slice(0,1)}</strong> ${char[attr]}</li>` : ''
   ).join('');

   return `
   <div class="detail-card" data-id="${char.姓名}">
    <div class="detail-header" style="border-color: ${borderColor};">
     <h2 class="char-name" style="color:${borderColor};">${char.姓名}</h2>
     <span class="char-title">${char.称号 || '幸存者'}</span>
    </div>
    <div class="details-grid">
     <div class="detail-section grid-full-width">
      <h3 class="detail-title">六维属性</h3>
      <ul class="attr-list">${attrHTML}</ul>
     </div>
     ${char.神力 ? `<div class="detail-section">
      <h3 class="detail-title">能量</h3>
      ${createProgressBar('能量值', char.神力.split('/')[0], char.神力.split('/')[1] || 100, borderColor)}
     </div>` : ''}
     <div class="detail-section">
      <h3 class="detail-title">状态</h3>
      <div class="detail-value">${char.状态 || '未知'}</div>
     </div>
      <div class="detail-section">
      <h3 class="detail-title">当前行动</h3>
      <div class="detail-value">${char.行动 || '无'}</div>
     </div>
     <div class="detail-section">
      <h3 class="detail-title">装备</h3>
      <div class="detail-value">${char.装备 || '无'}</div>
     </div>
     ${char.内心想法 ? `<div class="detail-section thought-section" style="border-left-color:${borderColor};">
      <h3 class="detail-title" style="color:${borderColor};">内心想法</h3>
      <div class="detail-value thought-value">"${char.内心想法}"</div>
     </div>` : ''}
    </div>
   </div>`;
  }

  const rawDataContainer = document.querySelector('.corruption-data-container');
  if (rawDataContainer) {
      const rawData = rawDataContainer.textContent;
      if(rawData && rawData.trim() !== ''){
       const data = parseData(rawData);
       renderUI(data);
       setupToggle();
      } else {
       const uiContainer = document.getElementById('corruption-ui');
       if(uiContainer) uiContainer.innerHTML = '<div style="padding:20px; text-align:center;">等待数据传入...</div>';
      }
  }
 });
 </script>
</body>
</html>
