  .progress-bar-label { font-size: 0.9em; margin-bottom: 4px; display: flex; justify-content: space-between; }
  .progress-bar-bg { background-color: var(--bar-bg); border-radius: 5px; height: 10px; overflow: hidden; }
  .progress-bar-fg { height: 100%; border-radius: 5px; transition: width 0.5s ease; }

  .thought-section { border-left-color: var(--primary-color); grid-column: 1 / -1; }
  .thought-value { font-style: italic; color: #dcdde1; opacity: 0.9;}

  ::-webkit-scrollbar { width: 6px; }
  ::-webkit-scrollbar-track { background: var(--bg-color); }
  ::-webkit-scrollbar-thumb { background: var(--border-color); border-radius: 3px; }
  ::-webkit-scrollbar-thumb:hover { background: var(--primary-color); }
 </style>
